/* Explicitly armed, exact read-only auth.sessions continuation receipt. */
const { Client } = require('pg'); const crypto = require('node:crypto');
const assert = (v, c) => { if (!v) throw new Error(c); }; const uuid = (v) => typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);
async function reconcileExactSession(receipt) { assert(uuid(receipt?.sessionId) && typeof receipt?.actorSha256 === 'string', 'exact_session_receipt_missing'); assert(process.env.MATRX_PROTON_COOKIE_SESSION_RECONCILE === 'READONLY_EXACT_SESSION_UNDER_REVIEW', 'inert_session_reconciliation_requires_explicit_arm'); const client = new Client({ connectionString: process.env.MATRX_CANONICAL_DATABASE_URL, statement_timeout: 10_000, query_timeout: 10_000 }); await client.connect(); try { const result = await client.query('SELECT id, user_id FROM auth.sessions WHERE id = $1 LIMIT 1', [receipt.sessionId]); assert(result.rows.length <= 1, 'exact_session_query_ambiguous'); if (result.rows.length === 0) return 'absent'; assert(crypto.createHash('sha256').update(result.rows[0].user_id).digest('hex') === receipt.actorSha256, 'exact_session_actor_mismatch'); return 'present'; } finally { await client.end(); } }
module.exports = { reconcileExactSession };
